<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/layout.php';
$user=require_super_admin();$rows=db()->query("SELECT l.*,a.name acting_name,f.name affected_name FROM Audit_Log l LEFT JOIN Users a ON a.user_id=l.acting_user_id LEFT JOIN Users f ON f.user_id=l.affected_user_id ORDER BY l.log_id DESC LIMIT 500")->fetchAll();
$body='<div class="table-card"><table class="table table-hover"><thead><tr><th>ID</th><th>Timestamp</th><th>Actor</th><th>Affected</th><th>Action</th><th>Previous</th><th>New</th><th>Description</th></tr></thead><tbody>';foreach($rows as$r){$body.='<tr><td>'.(int)$r['log_id'].'</td><td>'.e((string)$r['action_timestamp']).'</td><td>'.e((string)($r['acting_name']??'System')).'</td><td>'.e((string)($r['affected_name']??'N/A')).'</td><td>'.e($r['action']).'</td><td>'.e((string)$r['previous_value']).'</td><td>'.e((string)$r['new_value']).'</td><td>'.e((string)$r['description']).'</td></tr>';}$body.='</tbody></table></div>';render_layout('Audit Logs',$body,$user,true);
